mapper.insert:

    SELECT CONCAT('NTG', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_portal_common') AS
    varchar), 4, '0'))

INSERT
INTO dtmeta.tb_portal_notifctarget(  /* SQL_ID: NotifcTargetMapper.insertNotifcTarget */
    notifc_tgt_id
    , notifc_type_id
    , notifc_tgt_type_mtcd
    , notifc_tgt_div_mtcd
    , notifc_tgtr_ids
    , notifc_tgtr_nms
    , notifc_tgt_reg_dt
    , notifc_tgt_amd_dt
)
VALUES (
    #{notifcTgtId}
    , #{notifcTypeId}
    , #{notifcTgtTypeMtcd}
    , #{notifcTgtDivMtcd}
    , #{notifcTgtrIds}
    , #{notifcTgtrNms}
    , current_timestamp
    , current_timestamp
)

mapper.update:
UPDATE dtmeta.tb_portal_notifctarget   /* SQL_ID: NotifcTargetMapper.updateNotifcTarget */
SET
    notifc_type_id = #{notifcTypeId}
    , notifc_tgt_type_mtcd = #{notifcTgtTypeMtcd}
    , notifc_tgt_div_mtcd = #{notifcTgtDivMtcd}
    , notifc_tgtr_ids = #{notifcTgtrIds}
    , notifc_tgtr_nms = #{notifcTgtrNms}
    , notifc_tgt_amd_dt = current_timestamp
WHERE notifc_tgt_id = #{notifcTgtId}

mapper.select:
SELECT EXISTS (  /* SQL_ID: NotifcTargetMapper.isNotifcTgtIdExist */
    SELECT 1
    FROM dtmeta.tb_portal_notifctarget
    WHERE notifc_tgt_id = #{notifcTgtId}
)

mapper.delete:
DELETE   /* SQL_ID: NotifcTargetMapper.deleteNotifcTarget */
FROM dtmeta.tb_portal_notifctarget
WHERE notifc_tgt_id = #{notifcTgtId}
